var findLongestChain = function(pairs) {
    pairs.sort((a, b) => a[1] - b[1]);
    let curr = -Infinity;
    let ans = 0;
    for (const [a, b] of pairs) {
        if (a > curr) {
            curr = b;
            ans++;
        }
    }
    return ans;
};
